    'key-dr.png': '3',
    'arrow_single.png': '>',
    'arrow_double.png': '>>',
    'arrow_3.png': '-',
    'jump.png': 'Jump',
    'key-barrage.png': 'Hold',
    'key-barrage2.png': 'Hold2',
